-- RAKHAL-418 (1/2): prepare the schema for the diagnosis-field collapse without touching any
-- existing data destructively. Hand-authored (not `migrate dev`'s autogenerated diff) so the real
-- `diagnosis` text survives via a column RENAME rather than a drop+recreate, and `diagnosisType`
-- stays in place long enough for the backfill script (`prisma/rakhal-418-migrate-care-type.ts`) to
-- read it. Step 2 (`..._rakhal_418_care_type_finalize`) runs after that script and drops the old
-- column/type + tightens `careType` to NOT NULL.

-- New two-value enum, replacing the 8-value HealthDiagnosisType.
CREATE TYPE "HealthCareType" AS ENUM ('CURATIVE', 'PREVENTIVE');

-- `diagnosis` -> `note`: a rename preserves every existing row's free text; DROP NOT NULL matches
-- the new "optional free-text note" shape.
ALTER TABLE "HealthCase" RENAME COLUMN "diagnosis" TO "note";
ALTER TABLE "HealthCase" ALTER COLUMN "note" DROP NOT NULL;
ALTER INDEX "HealthCase_farmId_diagnosis_idx" RENAME TO "HealthCase_farmId_note_idx";

-- Added nullable for now — the backfill script populates it from the still-present
-- `diagnosisType` column before step 2 makes it NOT NULL.
ALTER TABLE "HealthCase" ADD COLUMN "careType" "HealthCareType";
